-- Preserve shared event/holiday metadata and restrict team-scoped announcements.
alter table public.events add column location text not null default '',add column organizer text not null default '',add column participants text not null default '',add column status text not null default 'Scheduled',add column category text not null default '',add column event_type text not null default '',add column department_id uuid references public.departments(id),add column created_by uuid references auth.users(id);
alter table public.holidays add column description text not null default '',add column status text not null default 'Active',add column category text not null default '',add column holiday_type text not null default '',add column department_id uuid references public.departments(id),add column created_by uuid references auth.users(id);
alter table public.holidays drop constraint holidays_day_key;
create function private.can_manage_calendar_item(p_department uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.memberships where user_id=auth.uid() and active and (role='admin' or (role='manager' and department_id=p_department))) $$;
drop policy events_read on public.events;drop policy holidays_read on public.holidays;
create policy events_read on public.events for select to authenticated using(private.is_member() and (department_id is null or private.is_admin() or department_id=(select m.department_id from public.memberships m where m.user_id=auth.uid())));
create policy holidays_read on public.holidays for select to authenticated using(private.is_member() and (department_id is null or private.is_admin() or department_id=(select m.department_id from public.memberships m where m.user_id=auth.uid())));
create function public.save_calendar_item(p_kind text,p_data jsonb,p_id uuid default null) returns uuid language plpgsql security definer set search_path='' as $$declare dep uuid;old_dep uuid;v uuid;begin
 perform private.assert_member();if private.is_admin() then dep:=nullif(p_data->>'department_id','')::uuid;else select department_id into dep from public.memberships where user_id=auth.uid() and role='manager';if dep is null then raise exception 'Manager access required.';end if;end if;
 if not private.can_manage_calendar_item(dep) then raise exception 'Calendar management is not permitted.';end if;
 if length(trim(p_data->>'name')) not between 1 and 120 or pg_column_size(p_data)>16000 then raise exception 'Invalid calendar details.';end if;
 if p_id is not null then
 if p_kind='event' then select department_id into old_dep from public.events where id=p_id for update;else select department_id into old_dep from public.holidays where id=p_id for update;end if;
 if not found or not private.can_manage_calendar_item(old_dep) then raise exception 'Item unavailable.';end if;end if;
 if p_kind='event' then
 insert into public.events(id,name,starts_at,ends_at,description,location,organizer,participants,status,category,event_type,department_id,created_by)
 values(coalesce(p_id,gen_random_uuid()),trim(p_data->>'name'),(p_data->>'starts_at')::timestamptz,(p_data->>'ends_at')::timestamptz,coalesce(p_data->>'description',''),coalesce(p_data->>'location',''),coalesce(p_data->>'organizer',''),coalesce(p_data->>'participants',''),coalesce(p_data->>'status','Scheduled'),coalesce(p_data->>'category',''),coalesce(p_data->>'type',''),dep,auth.uid())
 on conflict(id) do update set name=excluded.name,starts_at=excluded.starts_at,ends_at=excluded.ends_at,description=excluded.description,location=excluded.location,organizer=excluded.organizer,participants=excluded.participants,status=excluded.status,category=excluded.category,event_type=excluded.event_type,department_id=excluded.department_id returning id into v;
 elsif p_kind='holiday' then
 insert into public.holidays(id,name,day,description,status,category,holiday_type,department_id,created_by) values(coalesce(p_id,gen_random_uuid()),trim(p_data->>'name'),(p_data->>'day')::date,coalesce(p_data->>'description',''),coalesce(p_data->>'status','Active'),coalesce(p_data->>'category',''),coalesce(p_data->>'type',''),dep,auth.uid()) on conflict(id) do update set name=excluded.name,day=excluded.day,description=excluded.description,status=excluded.status,category=excluded.category,holiday_type=excluded.holiday_type,department_id=excluded.department_id returning id into v;
 else raise exception 'Unknown item type.';end if;
 if p_id is null then insert into public.notifications(user_id,title,body) select user_id,'New calendar '||p_kind,p_data->>'name' from public.memberships where active and user_id<>auth.uid() and (dep is null or department_id=dep);end if;perform private.audit('calendar.item_saved',v);return v;end;$$;
create function public.delete_calendar_item(p_kind text,p_id uuid) returns void language plpgsql security definer set search_path='' as $$declare dep uuid;begin perform private.assert_member();if p_kind='event' then select department_id into dep from public.events where id=p_id;elsif p_kind='holiday' then select department_id into dep from public.holidays where id=p_id;else raise exception 'Unknown item type.';end if;if not found or not private.can_manage_calendar_item(dep) then raise exception 'Item unavailable.';end if;if p_kind='event' then delete from public.events where id=p_id;else delete from public.holidays where id=p_id;end if;perform private.audit('calendar.item_deleted',p_id);end;$$;
-- Close the former unscoped creation path by delegating to the scoped command.
create or replace function public.create_calendar_item(p_kind text,p_name text,p_start timestamptz,p_end timestamptz,p_description text default '') returns uuid language plpgsql security definer set search_path='' as $$begin return public.save_calendar_item(p_kind,jsonb_build_object('name',p_name,'starts_at',p_start,'ends_at',p_end,'day',(p_start at time zone 'UTC')::date,'description',p_description));end;$$;
revoke all on function private.can_manage_calendar_item(uuid) from public,anon,authenticated;
revoke all on function public.save_calendar_item(text,jsonb,uuid),public.delete_calendar_item(text,uuid) from public,anon;
grant execute on function public.save_calendar_item(text,jsonb,uuid),public.delete_calendar_item(text,uuid) to authenticated;
